import { useState } from "react";
import Warehouse from "./Warehouse";
import Delivery from "./Delivery";
import Tasks from "./Tasks";
import DeliveryCalc from "./DeliveryCalc";
import Dashboard from "./Dashboard";
import Rotation from "./Rotation";

const ORGS = [
  { id: 0, label: "РћСЂРіР°РЅРёР·Р°С†РёСЏ 1", accent: "#1a5fa8", font: "'Georgia', serif", priceMultiplier: 1.0 },
  { id: 1, label: "РћСЂРіР°РЅРёР·Р°С†РёСЏ 2", accent: "#2e7d32", font: "'Trebuchet MS', sans-serif", priceMultiplier: 1.04 },
  { id: 2, label: "РћСЂРіР°РЅРёР·Р°С†РёСЏ 3", accent: "#6a1b9a", font: "'Palatino Linotype', serif", priceMultiplier: 1.06 },
];
const defaultOrgs = [
  { name: "", inn: "", address: "", phone: "", email: "", director: "" },
  { name: "", inn: "", address: "", phone: "", email: "", director: "" },
  { name: "", inn: "", address: "", phone: "", email: "", director: "" },
];
const defaultItems = [{ desc: "", qty: 1, unit: "С€С‚.", price: "" }];

function formatNum(n) {
  return Number(n).toLocaleString("ru-RU", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function genKP(orgData, org, items, client, description, deadline, kpDate, ndsMode) {
  const accent = org.accent, font = org.font, mult = org.priceMultiplier;
  const rows = items.map((it) => {
    const p = parseFloat(it.price) || 0, q = parseFloat(it.qty) || 0;
    return { ...it, unitPrice: p * mult, total: p * mult * q };
  });
  const grandTotal = rows.reduce((s, r) => s + r.total, 0);
  const nds = ndsMode === "with" ? grandTotal * 0.05 : 0;
  const withNds = grandTotal + nds;
  const totalsBlock = ndsMode === "with"
    ? `<div class="totals">РС‚РѕРіРѕ Р±РµР· РќР”РЎ: <b>${formatNum(grandTotal)} СЂСѓР±.</b></div><div class="totals">РќР”РЎ 5%: <b>${formatNum(nds)} СЂСѓР±.</b></div><div class="totals grand">РРўРћР“Рћ СЃ РќР”РЎ: ${formatNum(withNds)} СЂСѓР±.</div>`
    : `<div class="totals grand">РРўРћР“Рћ (Р±РµР· РќР”РЎ): ${formatNum(grandTotal)} СЂСѓР±.</div>`;
  const tableRows = rows.map((r, i) => `<tr style="background:${i%2===0?"#f9f9f9":"#fff"}"><td style="padding:6px 10px;border:1px solid #ddd;text-align:center">${i+1}</td><td style="padding:6px 10px;border:1px solid #ddd">${r.desc}</td><td style="padding:6px 10px;border:1px solid #ddd;text-align:center">${r.qty}</td><td style="padding:6px 10px;border:1px solid #ddd;text-align:center">${r.unit}</td><td style="padding:6px 10px;border:1px solid #ddd;text-align:right">${formatNum(r.unitPrice)}</td><td style="padding:6px 10px;border:1px solid #ddd;text-align:right">${formatNum(r.total)}</td></tr>`).join("");
  return `<!DOCTYPE html><html lang="ru"><head><meta charset="UTF-8"><title>РљРџ вЂ” ${orgData.name}</title><style>body{font-family:${font};font-size:13px;color:#222;margin:0;padding:0}.page{max-width:800px;margin:0 auto;padding:32px 40px}.header-bar{border-bottom:3px solid ${accent};padding-bottom:16px;margin-bottom:20px;display:flex;justify-content:space-between}.org-name{font-size:15px;font-weight:bold;color:${accent};margin-bottom:4px}.kp-title{text-align:center;font-size:17px;font-weight:bold;color:${accent};margin:18px 0 10px}.meta{font-size:12px;color:#555;margin-bottom:14px}.desc-block{margin-bottom:16px;line-height:1.6}table{width:100%;border-collapse:collapse;font-size:12px;margin-bottom:8px}th{background:${accent};color:#fff;padding:7px 10px;text-align:left;border:1px solid ${accent}}.totals{text-align:right;font-size:13px;margin:6px 0}.totals b,.grand{color:${accent}}.grand{font-size:15px;font-weight:bold;text-align:right;margin:6px 0}.footer{margin-top:30px;font-size:12px;color:#555;border-top:1px solid #ddd;padding-top:14px;display:flex;justify-content:space-between}.sign{margin-top:40px;font-size:12px}</style></head><body><div class="page"><div class="header-bar"><div><div class="org-name">${orgData.name}</div><div style="font-size:12px;color:#444">РРќРќ: ${orgData.inn}</div><div style="font-size:12px;color:#444">${orgData.address}</div><div style="font-size:12px;color:#444">${orgData.phone} | ${orgData.email}</div></div><div style="text-align:right;font-size:12px;color:#555"><div>Р”Р°С‚Р°: ${kpDate}</div><div>в„– РљРџ: ${Math.floor(Math.random()*900)+100}/${new Date().getFullYear()}</div></div></div><div class="kp-title">РљРћРњРњР•Р Р§Р•РЎРљРћР• РџР Р•Р”Р›РћР–Р•РќРР•</div><div class="meta"><b>Р—Р°РєР°Р·С‡РёРє:</b> ${client||"вЂ”"}<br><b>РЎСЂРѕРє РІС‹РїРѕР»РЅРµРЅРёСЏ:</b> ${deadline||"вЂ”"}</div><div class="desc-block"><b>РћРїРёСЃР°РЅРёРµ СЂР°Р±РѕС‚ / СѓСЃР»СѓРі:</b><br>${description||"вЂ”"}</div><table><thead><tr><th style="width:32px">в„–</th><th>РќР°РёРјРµРЅРѕРІР°РЅРёРµ</th><th style="width:50px">РљРѕР»-РІРѕ</th><th style="width:50px">Р•Рґ.</th><th style="width:90px">Р¦РµРЅР°, СЂСѓР±.</th><th style="width:100px">РЎСѓРјРјР°, СЂСѓР±.</th></tr></thead><tbody>${tableRows}</tbody></table>${totalsBlock}<div style="margin-top:16px;font-size:12px;color:#555">РџСЂРµРґР»РѕР¶РµРЅРёРµ РґРµР№СЃС‚РІРёС‚РµР»СЊРЅРѕ 30 РґРЅРµР№.</div><div class="sign"><p><b>Р”РёСЂРµРєС‚РѕСЂ:</b> ${orgData.director} / ___________________</p><p style="color:#aaa">Рњ.Рџ.</p></div><div class="footer"><div>${orgData.name}</div><div>${orgData.address}</div><div>${orgData.phone}</div></div></div></body></html>`;
}

export default function App() {
  const [tab, setTab] = useState("dashboard");
  const [step, setStep] = useState(0);
  const [orgs, setOrgs] = useState(defaultOrgs);
  const [client, setClient] = useState("");
  const [description, setDescription] = useState("");
  const [deadline, setDeadline] = useState("");
  const [kpDate, setKpDate] = useState(new Date().toLocaleDateString("ru-RU"));
  const [items, setItems] = useState(defaultItems);
  const [ndsModes, setNdsModes] = useState(["without","without","without"]);
  const [loading, setLoading] = useState(false);
  const [generated, setGenerated] = useState(false);
  const [activePreview, setActivePreview] = useState(0);
  const [htmls, setHtmls] = useState(["","",""]);

  const getBadge = (v) => {
    try {
      if (v==="tasks") { const t=JSON.parse(localStorage.getItem("tasks_items")||"[]"); const n=t.filter(t=>!t.done&&t.deadline&&new Date(t.deadline)<new Date().setHours(0,0,0,0)).length; return n>0?n:null; }
      if (v==="warehouse") { const w=JSON.parse(localStorage.getItem("warehouse_items")||"[]"); const n=w.filter(i=>i.qty===0).length; return n>0?n:null; }
    } catch {} return null;
  };

  const updateOrg=(i,f,v)=>{const o=[...orgs];o[i]={...o[i],[f]:v};setOrgs(o);};
  const updateItem=(i,f,v)=>{const it=[...items];it[i]={...it[i],[f]:v};setItems(it);};
  const addItem=()=>setItems([...items,{desc:"",qty:1,unit:"С€С‚.",price:""}]);
  const removeItem=(i)=>setItems(items.filter((_,idx)=>idx!==i));

  const generate=async()=>{
    setLoading(true);setGenerated(false);
    let descs=[description,description,description];
    try {
      const res=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:"claude-sonnet-4-20250514",max_tokens:1000,messages:[{role:"user",content:`РџРµСЂРµС„СЂР°Р·РёСЂСѓР№ РѕРїРёСЃР°РЅРёРµ С‚СЂРµРјСЏ СЃРїРѕСЃРѕР±Р°РјРё. JSON: {"v1":"...","v2":"...","v3":"..."}. РћСЂРёРіРёРЅР°Р»: "${description}"`}]})});
      const data=await res.json();
      const text=data.content?.map(b=>b.text||"").join("")||"";
      const parsed=JSON.parse(text.replace(/```json|```/g,"").trim());
      descs=[parsed.v1||description,parsed.v2||description,parsed.v3||description];
    } catch {}
    setHtmls(ORGS.map((org,i)=>genKP(orgs[i],org,items,client,descs[i],deadline,kpDate,ndsModes[i])));
    setLoading(false);setGenerated(true);setStep(2);
  };

  const downloadKP=(i)=>{const blob=new Blob([htmls[i]],{type:"text/html;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`РљРџ_${orgs[i].name||"РћСЂРі_"+(i+1)}.html`;a.click();URL.revokeObjectURL(url);};

  const S = {
    page: { background:"#0f1117", minHeight:"100vh", padding:"24px 16px" },
    wrap: { maxWidth:900, margin:"0 auto", fontFamily:"Inter,Arial,sans-serif", display:"flex", gap:0 },
    nav: { width:180, minWidth:180, marginRight:20 },
    navLabel: { color:"#7c8db5", fontSize:11, fontWeight:600, letterSpacing:"1px", textTransform:"uppercase", margin:"0 0 10px 8px" },
    navActive: { background:"linear-gradient(135deg,#3b5bdb,#7048e8)", borderRadius:10, padding:"11px 14px", marginBottom:4, display:"flex", alignItems:"center", gap:10, cursor:"pointer", border:"none", width:"100%", textAlign:"left" },
    navItem: { background:"transparent", borderRadius:10, padding:"11px 14px", marginBottom:4, display:"flex", alignItems:"center", gap:10, cursor:"pointer", border:"none", width:"100%", textAlign:"left" },
    content: { flex:1, minWidth:0 },
    card: { background:"#1e2130", border:"1px solid #2d3354", borderRadius:10, padding:"16px 20px", marginBottom:16 },
    inp: { width:"100%", boxSizing:"border-box", marginBottom:8, padding:"8px 12px", border:"1px solid #2d3354", borderRadius:8, fontSize:13, background:"#252a3d", color:"#e2e8f0" },
    lbl: { display:"block", fontSize:12, color:"#7c8db5", marginBottom:4 },
    btn: { padding:"8px 18px", borderRadius:8, border:"1px solid #2d3354", background:"#252a3d", cursor:"pointer", fontSize:13, color:"#e2e8f0" },
    btnPrimary: { padding:"8px 18px", borderRadius:8, border:"none", background:"linear-gradient(135deg,#3b5bdb,#7048e8)", cursor:"pointer", fontSize:13, color:"#fff", fontWeight:600 },
  };

  return (
    <div style={S.page}>
      <div style={S.wrap}>
        <div style={S.nav}>
          <p style={S.navLabel}>РњРµРЅСЋ</p>
          {[["dashboard","рџЏ ","Р“Р»Р°РІРЅР°СЏ"],["kp","рџ“„","Р“РµРЅРµСЂР°С‚РѕСЂ РљРџ"],["warehouse","рџ“¦","РЎРєР»Р°Рґ"],["delivery","рџљљ","Р”РѕСЃС‚Р°РІРєРё"],["tasks","рџ“‹","Р—Р°РґР°С‡Рё"],["calc","рџљ›","РљР°Р»СЊРєСѓР»СЏС‚РѕСЂ"],["rotation","рџ”„","Р РѕС‚Р°С†РёСЏ"]].map(([v,ic,l])=>(
            <button key={v} onClick={()=>setTab(v)} style={tab===v?S.navActive:S.navItem}>
              <span style={{fontSize:16}}>{ic}</span>
              <span style={{color:tab===v?"#fff":"#a0aec0",fontSize:14,fontWeight:tab===v?600:400}}>{l}</span>
              {getBadge(v)?<span style={{marginLeft:"auto",background:"#e53e3e",color:"#fff",borderRadius:10,padding:"1px 7px",fontSize:11,fontWeight:700}}>{getBadge(v)}</span>:null}
            </button>
          ))}
        </div>

        <div style={S.content}>
          {tab==="dashboard"&&<Dashboard setTab={setTab}/>}
          {tab==="warehouse"&&<Warehouse/>}
          {tab==="delivery"&&<Delivery/>}
          {tab==="tasks"&&<Tasks/>}
          {tab==="calc"&&<DeliveryCalc/>}
          {tab==="rotation"&&<Rotation/>}
          {tab==="kp"&&(
            <>
              {step!==2&&(
                <>
                  <div style={{display:"flex",gap:8,marginBottom:20}}>
                    {["Р”Р°РЅРЅС‹Рµ РљРџ","РћСЂРіР°РЅРёР·Р°С†РёРё"].map((t,i)=>(
                      <button key={i} onClick={()=>setStep(i)} style={{...S.btn,fontWeight:step===i?600:400,borderColor:step===i?"#3b5bdb":"#2d3354",color:step===i?"#748ffc":"#e2e8f0"}}>{i+1}. {t}</button>
                    ))}
                  </div>
                  {step===0&&(
                    <>
                      <div style={S.card}>
                        <p style={{fontWeight:600,marginBottom:12,fontSize:14,color:"#e2e8f0"}}>РћР±С‰РёРµ СЃРІРµРґРµРЅРёСЏ</p>
                        <label style={S.lbl}>Р—Р°РєР°Р·С‡РёРє</label><input style={S.inp} value={client} onChange={e=>setClient(e.target.value)} placeholder="РћРћРћ В«Р—Р°РєР°Р·С‡РёРєВ»"/>
                        <label style={S.lbl}>Р”Р°С‚Р° РљРџ</label><input style={{...S.inp,width:"auto"}} value={kpDate} onChange={e=>setKpDate(e.target.value)}/>
                        <label style={S.lbl}>РЎСЂРѕРє РІС‹РїРѕР»РЅРµРЅРёСЏ</label><input style={S.inp} value={deadline} onChange={e=>setDeadline(e.target.value)} placeholder="РЅР°РїСЂРёРјРµСЂ: 30 СЂР°Р±РѕС‡РёС… РґРЅРµР№"/>
                        <label style={S.lbl}>РћРїРёСЃР°РЅРёРµ СЂР°Р±РѕС‚ / СѓСЃР»СѓРі</label>
                        <textarea rows={4} style={{...S.inp,resize:"vertical"}} value={description} onChange={e=>setDescription(e.target.value)} placeholder="РћРїРёС€РёС‚Рµ СЂР°Р±РѕС‚С‹..."/>
                      </div>
                      <div style={S.card}>
                        <p style={{fontWeight:600,marginBottom:12,fontSize:14,color:"#e2e8f0"}}>РџРѕР·РёС†РёРё Рё С†РµРЅС‹</p>
                        <table style={{width:"100%",fontSize:12,borderCollapse:"collapse"}}>
                          <thead><tr style={{background:"#252a3d"}}>
                            <th style={{textAlign:"left",padding:"6px 8px",fontWeight:500,color:"#7c8db5"}}>РќР°РёРјРµРЅРѕРІР°РЅРёРµ</th>
                            <th style={{width:60,textAlign:"center",padding:"6px 8px",fontWeight:500,color:"#7c8db5"}}>РљРѕР»-РІРѕ</th>
                            <th style={{width:70,textAlign:"center",padding:"6px 8px",fontWeight:500,color:"#7c8db5"}}>Р•Рґ.</th>
                            <th style={{width:110,textAlign:"right",padding:"6px 8px",fontWeight:500,color:"#7c8db5"}}>Р¦РµРЅР° (Р±Р°Р·Р°)</th>
                            <th style={{width:30}}></th>
                          </tr></thead>
                          <tbody>
                            {items.map((it,i)=>(
                              <tr key={i}>
                                <td style={{padding:"3px 4px"}}><input value={it.desc} onChange={e=>updateItem(i,"desc",e.target.value)} style={{...S.inp,marginBottom:0}} placeholder="РќР°Р·РІР°РЅРёРµ РїРѕР·РёС†РёРё"/></td>
                                <td style={{padding:"3px 4px"}}><input type="number" value={it.qty} onChange={e=>updateItem(i,"qty",e.target.value)} style={{...S.inp,marginBottom:0,textAlign:"center"}}/></td>
                                <td style={{padding:"3px 4px"}}><input value={it.unit} onChange={e=>updateItem(i,"unit",e.target.value)} style={{...S.inp,marginBottom:0}}/></td>
                                <td style={{padding:"3px 4px"}}><input type="number" value={it.price} onChange={e=>updateItem(i,"price",e.target.value)} style={{...S.inp,marginBottom:0,textAlign:"right"}} placeholder="0"/></td>
                                <td style={{padding:"3px 4px",textAlign:"center"}}>{items.length>1&&<button onClick={()=>removeItem(i)} style={{...S.btn,padding:"4px 8px",color:"#fc8181"}}>вњ•</button>}</td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                        <button onClick={addItem} style={{...S.btn,marginTop:10,color:"#748ffc"}}>+ Р”РѕР±Р°РІРёС‚СЊ РїРѕР·РёС†РёСЋ</button>
                      </div>
                      <div style={{textAlign:"right"}}><button onClick={()=>setStep(1)} style={S.btnPrimary}>Р”Р°Р»РµРµ: РћСЂРіР°РЅРёР·Р°С†РёРё в†’</button></div>
                    </>
                  )}
                  {step===1&&(
                    <>
                      {ORGS.map((org,i)=>(
                        <div key={i} style={{...S.card,borderLeft:`4px solid ${org.accent}`}}>
                          <p style={{fontWeight:600,marginBottom:12,fontSize:14,color:org.accent}}>{org.label} <span style={{fontSize:11,color:"#7c8db5",fontWeight:400}}>(Г—{(org.priceMultiplier*100).toFixed(0)}%)</span></p>
                          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"0 16px"}}>
                            {[["name","РќР°Р·РІР°РЅРёРµ"],["inn","РРќРќ"],["address","РђРґСЂРµСЃ"],["phone","РўРµР»РµС„РѕРЅ"],["email","E-mail"],["director","Р”РёСЂРµРєС‚РѕСЂ"]].map(([f,l])=>(
                              <div key={f}><label style={S.lbl}>{l}</label><input style={S.inp} value={orgs[i][f]} onChange={e=>updateOrg(i,f,e.target.value)}/></div>
                            ))}
                          </div>
                          <div style={{marginTop:10}}>
                            <label style={S.lbl}>РќР”РЎ</label>
                            <div style={{display:"flex",gap:8}}>
                              {[["without","Р‘РµР· РќР”РЎ"],["with","РЎ РќР”РЎ (5%)"]].map(([v,l])=>(
                                <button key={v} onClick={()=>{const m=[...ndsModes];m[i]=v;setNdsModes(m);}} style={{padding:"5px 14px",borderRadius:8,border:`1px solid ${ndsModes[i]===v?org.accent:"#2d3354"}`,background:ndsModes[i]===v?"#252a3d":"transparent",color:ndsModes[i]===v?org.accent:"#a0aec0",cursor:"pointer",fontSize:13}}>{l}</button>
                              ))}
                            </div>
                          </div>
                        </div>
                      ))}
                      <div style={{display:"flex",justifyContent:"space-between",marginTop:8}}>
                        <button onClick={()=>setStep(0)} style={S.btn}>в†ђ РќР°Р·Р°Рґ</button>
                        <button onClick={generate} disabled={loading} style={S.btnPrimary}>{loading?"Р“РµРЅРµСЂР°С†РёСЏ...":"РЎРіРµРЅРµСЂРёСЂРѕРІР°С‚СЊ 3 РљРџ в†’"}</button>
                      </div>
                    </>
                  )}
                </>
              )}
              {generated&&step===2&&(
                <>
                  <p style={{fontSize:13,color:"#7c8db5",marginBottom:16}}>3 РљРџ РіРѕС‚РѕРІС‹.</p>
                  <div style={{display:"flex",gap:8,marginBottom:12,flexWrap:"wrap"}}>
                    {ORGS.map((org,i)=>(<button key={i} onClick={()=>setActivePreview(i)} style={{...S.btn,fontWeight:activePreview===i?600:400,borderColor:activePreview===i?org.accent:"#2d3354",color:activePreview===i?org.accent:"#e2e8f0"}}>{orgs[i].name||org.label}</button>))}
                  </div>
                  <div style={{display:"flex",gap:8,marginBottom:12}}>
                    <button onClick={()=>downloadKP(activePreview)} style={S.btnPrimary}>в¬‡ РЎРєР°С‡Р°С‚СЊ РљРџ {activePreview+1}</button>
                    <button onClick={()=>{setGenerated(false);setStep(0);}} style={S.btn}>в†ђ РќР°Р·Р°Рґ</button>
                  </div>
                  <div style={{border:"1px solid #2d3354",borderRadius:10,overflow:"hidden"}}>
                    <iframe key={activePreview} srcDoc={htmls[activePreview]} style={{width:"100%",height:600,border:"none"}} title={`РљРџ ${activePreview+1}`}/>
                  </div>
                  <p style={{fontSize:11,color:"#7c8db5",marginTop:8}}>Ctrl+P в†’ В«РЎРѕС…СЂР°РЅРёС‚СЊ РєР°Рє PDFВ» РґР»СЏ СЃРѕС…СЂР°РЅРµРЅРёСЏ.</p>
                </>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}